# ---------- DOM representation ----------

class Node:
    def __init__(self, tag=None, attrs=None, text=None, is_text=False, is_comment=False):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []
        self.parent = None
        self.text = text or ""
        self.is_text = is_text
        self.is_comment = is_comment
    def add(self, n):
        n.parent = self
        self.children.append(n)
    def classes(self):
        return (self.attrs.get("class", "") or "").split()

VOID_TAGS = {"area","base","br","col","embed","hr","img","input","link","meta","param","source","track","wbr"}
SKIP_CONTENT_TAGS = {"script","style","noscript","template"}
BLOCK_TAGS = {"address","article","aside","blockquote","canvas","dd","div","dl","dt","fieldset","figcaption","figure","footer","form","h1","h2","h3","h4","h5","h6","header","hr","li","main","nav","noscript","ol","output","p","pre","section","table","tfoot","thead","tbody","tr","td","th","ul","video","audio","iframe","details","summary"}

# A parser that collects children and handles void tags. Tolerant of mis-nesting.
class DomBuilder(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.root = Node(tag="__root__")
        self.stack = [self.root]
        self._skip_stack = 0
        self._skip_kind = None
    def _cur(self):
        return self.stack[-1]
    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        # If we're inside <script>/<style>, ignore all "tags" until matching close
        if self._skip_stack:
            # HTMLParser normally doesn't emit tags inside script/style,
            # but we guard anyway.
            return
        if tag in SKIP_CONTENT_TAGS:
            self._skip_stack += 1
            self._skip_kind = tag
            # don't add to tree
            return
        n = Node(tag=tag, attrs={k: (v if v is not None else "") for k,v in attrs})
        self._cur().add(n)
        if tag not in VOID_TAGS:
            self.stack.append(n)
    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        if self._skip_stack:
            return
        n = Node(tag=tag, attrs={k: (v if v is not None else "") for k,v in attrs})
        self._cur().add(n)
    def handle_endtag(self, tag):
        tag = tag.lower()
        if self._skip_stack:
            if tag == self._skip_kind:
                self._skip_stack -= 1
                if self._skip_stack == 0:
                    self._skip_kind = None
            return
        if tag in VOID_TAGS:
            return
        # pop up until we find matching tag
        for i in range(len(self.stack)-1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return
        # no match; ignore
    def handle_data(self, data):
        if self._skip_stack:
            return
        if not data:
            return
        self._cur().add(Node(is_text=True, text=data))
    def handle_entityref(self, name):
        if self._skip_stack:
            return
        # reconstruct as &name;
        entity = "&"+name+";"
        self._cur().add(Node(is_text=True, text=entity))
    def handle_charref(self, name):
        if self._skip_stack:
            return
        entity = "&#"+name+";"
        self._cur().add(Node(is_text=True, text=entity))
    def handle_comment(self, data):
        if self._skip_stack:
            return
        # ignore comments entirely
        return
    def handle_decl(self, decl):
        return
    def handle_pi(self, data):
        return
