# ---------- Entity decoding for text ----------
# Decodes all HTML entities except &lt; and &gt; (kept literal).
_ENT_RE = re.compile(r'&(#x[0-9a-fA-F]+|#[0-9]+|[A-Za-z][A-Za-z0-9]*);')

def decode_text_keep_lt_gt(s):
    def repl(m):
        e = m.group(0)
        if e == "&lt;" or e == "&gt;":
            return e
        # convert
        return html_mod.unescape(e)
    return _ENT_RE.sub(repl, s)

def decode_all(s):
    return html_mod.unescape(s)

# ---------- CSS selector matching (subset) ----------
# Supports: tag, #id, .class, attribute [foo="bar"], comma lists, descendant combinators

def _parse_simple(sel):
    # Returns list of (tag, id, classes, attrs). attrs=[(name,op,value)]
    tag = None
    id_ = None
    classes = []
    attrs = []
    i = 0
    # read tag
    m = re.match(r'[A-Za-z][A-Za-z0-9_-]*|\*', sel)
    if m:
        tag = m.group(0)
        if tag == "*":
            tag = None
        i = m.end()
    while i < len(sel):
        c = sel[i]
        if c == '#':
            m = re.match(r'[A-Za-z0-9_-]+', sel[i+1:])
            if not m: return None
            id_ = m.group(0)
            i += 1 + m.end()
        elif c == '.':
            m = re.match(r'[A-Za-z0-9_-]+', sel[i+1:])
            if not m: return None
            classes.append(m.group(0))
            i += 1 + m.end()
        elif c == '[':
            end = sel.find(']', i)
            if end < 0: return None
            body = sel[i+1:end]
            m = re.match(r'([A-Za-z_][A-Za-z0-9_-]*)\s*(?:(=|~=|\|=|\^=|\$=|\*=)\s*("[^"]*"|\'[^\']*\'|[^\s\]]+))?', body)
            if not m: return None
            name = m.group(1)
            op = m.group(2) or "present"
            val = m.group(3) or ""
            if val.startswith('"') and val.endswith('"'):
                val = val[1:-1]
            elif val.startswith("'") and val.endswith("'"):
                val = val[1:-1]
            attrs.append((name, op, val))
            i = end + 1
        else:
            return None
    return (tag, id_, classes, attrs)

def _node_matches_simple(node, sel):
    tag, id_, classes, attrs = sel
    if tag is not None and node.tag != tag:
        return False
    if id_ is not None and node.attrs.get("id") != id_:
        return False
    node_classes = set(node.classes())
    for c in classes:
        if c not in node_classes:
            return False
    for name, op, val in attrs:
        if name not in node.attrs:
            return False
        av = node.attrs.get(name, "")
        if op == "present":
            continue
        elif op == "=":
            if av != val: return False
        elif op == "~=":
            if val not in av.split(): return False
        elif op == "|=":
            if av != val and not av.startswith(val+"-"): return False
        elif op == "^=":
            if not av.startswith(val): return False
        elif op == "$=":
            if not av.endswith(val): return False
        elif op == "*=":
            if val not in av: return False
    return True

def _split_top_level_commas(s):
    parts = []
    depth = 0
    cur = []
    inq = None
    for ch in s:
        if inq:
            cur.append(ch)
            if ch == inq:
                inq = None
            continue
        if ch in ('"', "'"):
            inq = ch; cur.append(ch); continue
        if ch == '[':
            depth += 1; cur.append(ch); continue
        if ch == ']':
            depth -= 1; cur.append(ch); continue
        if ch == ',' and depth == 0:
            parts.append("".join(cur).strip()); cur = []; continue
        cur.append(ch)
    if cur:
        parts.append("".join(cur).strip())
    return parts

def _parse_selector(sel):
    """Return list of selector groups. Each group is a list of simple selectors (parsed), with combinator=' ' between them."""
    groups = []
    for part in _split_top_level_commas(sel):
        toks = re.split(r'\s+', part.strip())
        simples = []
        for t in toks:
            if not t: continue
            p = _parse_simple(t)
            if p is None:
                return None
            simples.append(p)
        if simples:
            groups.append(simples)
    return groups

def _matches_group(node, group):
    # group is list of simple selectors for descendant match.
    # the last must match node, earlier must match some ancestor in order.
    if not group: return False
    if not _node_matches_simple(node, group[-1]):
        return False
    i = len(group) - 2
    anc = node.parent
    while i >= 0 and anc is not None:
        if _node_matches_simple(anc, group[i]):
            i -= 1
        anc = anc.parent
    return i < 0

def node_matches_selector(node, selector):
    if not node or node.is_text or node.is_comment or node.tag == "__root__":
        return False
    groups = _parse_selector(selector)
    if not groups:
        return False
    for g in groups:
        if _matches_group(node, g):
            return True
    return False

def walk(node):
    yield node
    for c in list(node.children):
        yield from walk(c)

def remove_matching(root, selectors):
    if not selectors: return
    # Apply each
    combined = ", ".join(selectors)
    to_remove = []
    for n in walk(root):
        if node_matches_selector(n, combined):
            to_remove.append(n)
    for n in to_remove:
        if n.parent and n in n.parent.children:
            n.parent.children.remove(n)

def filter_include(root, selectors):
    if not selectors: return root
    combined = ", ".join(selectors)
    matches = []
    for n in walk(root):
        if node_matches_selector(n, combined):
            matches.append(n)
    # Create a new root with just the matched nodes (detached, not nesting issue)
    # Keep them in original order, skipping a match that is a descendant of another match
    filtered = []
    for m in matches:
        p = m.parent
        skip = False
        while p is not None and p.tag != "__root__":
            if p in matches:
                skip = True
                break
            p = p.parent
        if not skip:
            filtered.append(m)
    new_root = Node(tag="__root__")
    for m in filtered:
        # detach
        m.parent = new_root
        new_root.children.append(m)
    return new_root
