# ---------- Conversion to markdown ----------

class Options:
    def __init__(self):
        self.domain = ""
        self.strong_delim = "**"
        self.plugin_table = False
        self.plugin_strike = False
        self.table_padding = "aligned"
        self.table_header_promotion = False
        self.table_newline = "skip"
        self.table_presentation = False
        self.table_skip_empty_rows = False
        self.table_span = "empty"
        self.include_selectors = []
        self.exclude_selectors = []

INLINE_TAGS = {"a","abbr","b","bdi","bdo","cite","code","data","dfn","em","i","kbd","mark","q","s","samp","small","span","strong","sub","sup","time","u","var","wbr","br","img","del","ins","strike","tt"}

def is_block_ish(n):
    if n.is_text or n.is_comment: return False
    return n.tag not in INLINE_TAGS

def node_text(n):
    """Concatenate all text descendants (raw entity decoded for non-pre)."""
    parts = []
    for d in walk(n):
        if d.is_text:
            parts.append(d.text)
    return "".join(parts)

def all_children_text(n):
    return node_text(n)

def resolve_url(opts, url, is_link=True):
    if not url:
        return url
    if not opts.domain:
        return _percent_encode_url(url)
    # resolve
    base = opts.domain
    if not re.match(r'^[a-zA-Z][a-zA-Z0-9+.-]*://', base):
        # no scheme — default to http
        base = "http://" + base
    if not base.endswith("/"):
        # treat it like a directory? Actually no; urljoin handles
        pass
    try:
        joined = urljoin(base, url)
    except Exception:
        joined = url
    return _percent_encode_url(joined)

def _percent_encode_url(u):
    # Percent-encode characters needed; keep common URL chars.
    safe = "!#$&'*+,/:;=?@~[]()"  # will then handle ( ) specially
    # Actually we want to percent-encode: space, parentheses, non-ASCII, and some others.
    # Use quote with a generous safe set but encode parens.
    safe = ":/?#[]@!$&'*+,;=%~"
    try:
        return quote(u, safe=safe)
    except Exception:
        return u

def render_attr_title(title):
    # Use " unless title contains " ; else use '
    if not title:
        return ""
    if '"' in title:
        return " '" + title + "'"
    return ' "' + title + '"'
