def node_is_inline(n):
    if n.is_text: return True
    if n.is_comment: return True
    if not n.tag or n.tag == "__root__": return False
    return n.tag in INLINE_TAGS

def group_children(node):
    """Split node's children into groups: sequences of inline nodes (as inline blocks) vs block nodes."""
    groups = []
    cur = []
    for c in node.children:
        if c.is_comment:
            continue
        if node_is_inline(c) or c.is_text:
            cur.append(c)
        else:
            if cur:
                # strip leading/trailing whitespace text nodes to avoid empty inline groups
                groups.append(("inline", cur))
                cur = []
            groups.append(("block", c))
    if cur:
        groups.append(("inline", cur))
    return groups

def render_inline_group(children, ctx):
    # Build temp node-like and render inline
    temp = Node(tag="__tmp__")
    for c in children:
        temp.children.append(c)
    s = render_inline(temp, ctx)
    return s

def render_block(node, ctx, list_state=None):
    """Render a block element. Returns markdown string (no trailing blank line)."""
    tag = node.tag
    opts = ctx.opts
    if tag in ("h1","h2","h3","h4","h5","h6"):
        level = int(tag[1])
        inner = render_inline(node, ctx).strip()
        if not inner:
            return ""
        return ("#"*level) + " " + inner
    if tag == "p":
        inner = render_inline(node, ctx).strip()
        if not inner:
            return ""
        return _block_escape_lines(inner)
    if tag == "hr":
        return "* * *"
    if tag == "pre":
        # Code block
        # find language on code child
        lang = ""
        code_node = None
        for c in node.children:
            if not c.is_text and c.tag == "code":
                code_node = c; break
        target = code_node if code_node is not None else node
        if code_node is not None:
            cls = code_node.attrs.get("class", "")
            m = re.search(r'language-([A-Za-z0-9_+.-]+)', cls)
            if m: lang = m.group(1)
        # preserve text
        sub = RenderContext(opts)
        sub.in_pre = True
        sub.escape = False
        raw = render_inline(target, sub)
        # remove leading single newline commonly generated
        raw = raw
        return "```" + lang + "\n" + raw + "\n```"
    if tag == "blockquote":
        inner = render_children_block(node, ctx)
        lines = inner.split('\n')
        out = []
        for ln in lines:
            if ln == "":
                out.append(">")
            else:
                out.append("> " + ln)
        return '\n'.join(out)
    if tag in ("ul","ol"):
        return render_list(node, ctx)
    if tag == "li":
        # shouldn't be called directly typically
        return render_children_block(node, ctx)
    if tag == "table" and opts.plugin_table:
        return render_table(node, ctx)
    if tag in ("figure","figcaption","details","summary","dl","dt","dd","section","article","header","footer","nav","main","aside","form","fieldset","div","table","tbody","thead","tfoot","tr","td","th"):
        return render_children_block(node, ctx)
    # Fallback: render children as blocks
    return render_children_block(node, ctx)

def render_children_block(node, ctx):
    parts = []
    groups = group_children(node)
    # Process inline whitespace: combine and strip
    prev_was_block = True
    for kind, item in groups:
        if kind == "inline":
            s = render_inline_group(item, ctx).strip()
            if not s:
                continue
            s = _block_escape_lines(s)
            parts.append(s)
        else:
            s = render_block(item, ctx)
            if not s:
                continue
            parts.append(s)
    # Join with blank line between blocks
    return '\n\n'.join(parts)
