def render_list(node, ctx):
    ordered = node.tag == "ol"
    start = 1
    if ordered:
        try:
            start = int(node.attrs.get("start", "1") or 1)
        except Exception:
            start = 1
    items = [c for c in node.children if (not c.is_text and not c.is_comment and c.tag == "li")]
    out_items = []
    for idx, li in enumerate(items):
        marker = f"{start+idx}. " if ordered else "- "
        content = render_li_content(li, ctx)
        # indent subsequent lines
        indent = " " * len(marker)
        lines = content.split('\n')
        rendered = marker + lines[0] if lines else marker
        for ln in lines[1:]:
            rendered += '\n' + (indent + ln if ln else "")
        out_items.append(rendered)
    return '\n'.join(out_items)

def render_li_content(li, ctx):
    # Render li children as blocks, but if just inline content then single line.
    groups = group_children(li)
    # Simplify: if only one inline group and no block → one line
    if len(groups) == 1 and groups[0][0] == "inline":
        s = render_inline_group(groups[0][1], ctx).strip()
        s = _block_escape_lines(s)
        return s
    # If only one block group and it's a <p> → one line (like "simple" p only)
    if len(groups) == 1 and groups[0][0] == "block" and groups[0][1].tag == "p":
        return render_block(groups[0][1], ctx)
    # Else: render mix with \n\n between. But within li we want leading blank lines for sub-blocks.
    # Produce: first inline line then blank line then next blocks
    parts = []
    for kind, item in groups:
        if kind == "inline":
            s = render_inline_group(item, ctx).strip()
            if s:
                s = _block_escape_lines(s)
                parts.append(s)
        else:
            s = render_block(item, ctx)
            if s:
                parts.append(s)
    if not parts: return ""
    # First part joins as-is, rest joined with blank line
    first = parts[0]
    rest = parts[1:]
    if not rest:
        return first
    return first + '\n\n' + '\n\n'.join(rest)

def render_table(node, ctx):
    # Collect rows
    opts = ctx.opts
    rows = []  # list of rows, each row is list of (text, align)
    has_newline = False
    def collect_rows(n):
        for c in n.children:
            if c.is_text or c.is_comment: continue
            if c.tag in ("thead","tbody","tfoot"):
                collect_rows(c)
            elif c.tag == "tr":
                row = []
                for cc in c.children:
                    if cc.is_text or cc.is_comment: continue
                    if cc.tag in ("td","th"):
                        # render inline
                        sub = RenderContext(opts)
                        text = render_inline(cc, sub).strip()
                        align = (cc.attrs.get("align") or "").lower() or None
                        is_header = (cc.tag == "th")
                        row.append({"text": text, "align": align, "header": is_header})
                if row:
                    rows.append(row)
            else:
                collect_rows(c)
    collect_rows(node)
    if not rows:
        return ""
    # check for newlines
    for r in rows:
        for cell in r:
            if '\n' in cell['text']:
                has_newline = True
    if has_newline and opts.table_newline == "skip":
        # fallback: render as joined inline
        return render_children_block(node, ctx)
    # header handling: if first row has header cells (th) OR header promotion
    first_row_is_header = any(c["header"] for c in rows[0])
    if opts.table_header_promotion and not first_row_is_header:
        first_row_is_header = True
    if first_row_is_header:
        header = rows[0]
        data_rows = rows[1:]
    else:
        # empty header
        width = max(len(r) for r in rows)
        header = [{"text": "", "align": None, "header": True}] * width
        data_rows = rows
    width = max([len(header)] + [len(r) for r in rows])
    # pad rows
    def pad(r):
        while len(r) < width:
            r.append({"text": "", "align": None, "header": False})
        return r
    header = pad(list(header))
    data_rows = [pad(list(r)) for r in data_rows]
    # determine column widths based on padding option
    padding = opts.table_padding
    col_widths = [0]*width
    if padding == "aligned":
        for r in [header] + data_rows:
            for i, cell in enumerate(r):
                col_widths[i] = max(col_widths[i], len(cell["text"]))
        col_widths = [max(3, w) for w in col_widths]
    def cell_str(txt, w):
        if padding == "none":
            return txt
        if padding == "minimal":
            return " " + txt + " "
        # aligned
        return " " + txt + " " * (w - len(txt)) + " "
    def sep_str(align, w):
        if padding == "none":
            if align == "left": return ":--"
            if align == "right": return "--:"
            if align == "center": return ":-:"
            return "---"
        if padding == "minimal":
            if align == "left": return ":--"
            if align == "right": return "--:"
            if align == "center": return ":-:"
            return "---"
        # aligned: width based
        if align == "left":
            return ":" + "-" * (w + 1)
        if align == "right":
            return "-" * (w + 1) + ":"
        if align == "center":
            return ":" + "-" * w + ":"
        return "-" * (w + 2)
    # Build rows
    def join(cells, widths, is_sep=False):
        if is_sep:
            parts = cells
        else:
            parts = [cell_str(c["text"], widths[i]) for i,c in enumerate(cells)]
        return "|" + "|".join(parts) + "|"
    lines = []
    lines.append(join(header, col_widths))
    # alignment come from header alignment primarily
    aligns = [h.get("align") for h in header]
    lines.append(join([sep_str(aligns[i], col_widths[i]) for i in range(width)], col_widths, is_sep=True))
    for r in data_rows:
        lines.append(join(r, col_widths))
    return '\n'.join(lines)
